function drawStation(c){for(let i=1;i<systems.length;i++){const s=systems[i],p=worldToScreen(s.x,s.y,c);if(p.x< -80||p.x>W+80||p.y< -80||p.y>H+80)continue;const pulse=1+Math.sin(state.frame*.0015+i)*.08;ctx.save();ctx.translate(p.x,p.y);ctx.scale(pulse,pulse);ctx.shadowBlur=22;ctx.shadowColor=s.color;ctx.strokeStyle=s.color;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(0,0,29,0,6.28);ctx.stroke();ctx.beginPath();ctx.arc(0,0,20,0,6.28);ctx.strokeStyle=s.color+'55';ctx.stroke();ctx.rotate(state.frame*.0001);ctx.beginPath();ctx.moveTo(-38,0);ctx.lineTo(-25,0);ctx.moveTo(25,0);ctx.lineTo(38,0);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(0,0,5,0,6.28);ctx.fill();ctx.restore();ctx.font='10px "Space Mono"';ctx.fillStyle=s.color;ctx.textAlign='center';ctx.fillText(s.name.toUpperCase(),p.x,p.y+49)}}
function drawLoot(l,c){const p=worldToScreen(l.x,l.y,c);if(p.x< -20||p.x>W+20||p.y< -20||p.y>H+20)return;const bob=Math.sin(state.frame*.004+l.phase)*3;ctx.save();ctx.translate(p.x,p.y+bob);ctx.rotate(state.frame*.001);ctx.shadowBlur=13;ctx.shadowColor=l.type==='ore'?'#f7b85d':'#6de5e7';ctx.strokeStyle=l.type==='ore'?'#f7b85d':'#6de5e7';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(7,0);ctx.lineTo(0,8);ctx.lineTo(-7,0);ctx.closePath();ctx.stroke();ctx.restore()}
function drawEnemy(e,c){const p=worldToScreen(e.x,e.y,c);if(p.x< -50||p.x>W+50||p.y< -50||p.y>H+50)return;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(e.a);ctx.shadowBlur=14;ctx.shadowColor='#ff6677';ctx.beginPath();ctx.moveTo(20,0);ctx.lineTo(0,-14);ctx.lineTo(-17,-9);ctx.lineTo(-9,0);ctx.lineTo(-17,9);ctx.lineTo(0,14);ctx.closePath();ctx.fillStyle='#381d2a';ctx.fill();ctx.strokeStyle='#ff7884';ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.arc(0,0,3,0,6.28);ctx.fillStyle='#ffb7a2';ctx.fill();ctx.restore();ctx.fillStyle='#ff6677';ctx.fillRect(p.x-15,p.y-24,30*(e.hp/3),2)}
function drawShots(c){for(const s of state.shots){const p=worldToScreen(s.x,s.y,c);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-s.vx*.025,p.y-s.vy*.025);ctx.strokeStyle=s.player?'#a8ffff':'#ff7487';ctx.shadowBlur=10;ctx.shadowColor=ctx.strokeStyle;ctx.lineWidth=s.player?2.3:2;ctx.stroke()}ctx.shadowBlur=0}
function drawParticles(c,dt){for(const p of state.particles){const q=worldToScreen(p.x,p.y,c);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(q.x,q.y,p.r*Math.max(.2,p.life/p.max),0,6.28);ctx.fill()}ctx.globalAlpha=1}
function drawPlayer(){const p={x:W/2,y:H/2};if(Math.hypot(state.vx,state.vy)>45){ctx.fillStyle='#ffb16b';ctx.globalAlpha=.6;ctx.beginPath();ctx.moveTo(p.x-13*Math.cos(state.a),p.y-13*Math.sin(state.a));ctx.lineTo(p.x-28*Math.cos(state.a)+5*Math.sin(state.a),p.y-28*Math.sin(state.a)-5*Math.cos(state.a));ctx.lineTo(p.x-28*Math.cos(state.a)-5*Math.sin(state.a),p.y-28*Math.sin(state.a)+5*Math.cos(state.a));ctx.fill();ctx.globalAlpha=1}drawShip(state.x,state.y,state.a,1,'#6de5e7',true)}
function drawRadar(){const cx=W-101,cy=H-101,r=62;if(W<760)return;ctx.save();ctx.globalAlpha=.78;ctx.fillStyle='#06121ddd';ctx.strokeStyle='#6de5e733';ctx.beginPath();ctx.arc(cx,cy,r,0,6.28);ctx.fill();ctx.stroke();ctx.strokeStyle='#6de5e71c';ctx.beginPath();ctx.moveTo(cx-r,cy);ctx.lineTo(cx+r,cy);ctx.moveTo(cx,cy-r);ctx.lineTo(cx,cy+r);ctx.stroke();function dot(x,y,color,size){let dx=x-state.x,dy=y-state.y,f=Math.min(1,r/Math.max(1,Math.hypot(dx,dy))/1.18);ctx.fillStyle=color;ctx.beginPath();ctx.arc(cx+dx*f*.12,cy+dy*f*.12,size,0,6.28);ctx.fill()}for(const s of systems.slice(1))dot(s.x,s.y,s.color,2.2);for(const e of state.enemies)dot(e.x,e.y,'#ff6677',2);for(const l of state.loot)dot(l.x,l.y,'#f7b85d',1.5);ctx.fillStyle='#e7ffff';ctx.beginPath();ctx.arc(cx,cy,2.5,0,6.28);ctx.fill();ctx.font='8px "Space Mono"';ctx.fillStyle='#a1b7c0';ctx.textAlign='center';ctx.fillText('SCOPE',cx,cy+r+15);ctx.restore()}
function render(dt){const c=camera();drawBackground(c,dt);drawStation(c);for(const r of state.rocks)drawRock(r,c);for(const l of state.loot)drawLoot(l,c);for(const e of state.enemies)drawEnemy(e,c);drawShots(c);drawParticles(c,dt);drawPlayer();drawRadar();drawInteractionHint()}
function drawInteractionHint(){let near=null,best=190;for(let i=0;i<systems.length;i++){const d=Math.hypot(systems[i].x-state.x,systems[i].y-state.y);if(d<best){best=d;near=i}}if(near!==null){ctx.save();ctx.textAlign='center';ctx.fillStyle='#6de5e7';ctx.font='10px "Space Mono"';ctx.fillText(`E  DOCK AT ${systems[near].name.toUpperCase()}`,W/2,H/2+74);ctx.restore()}}
function update(dt){if(state.paused)return;state.frame+=dt*1000;const k=state.keys;let thrust=0;if(k.KeyW||k.ArrowUp)thrust=1;if(k.KeyS||k.ArrowDown)thrust=-.65;if(k.KeyA)state.a-=2.7*dt;if(k.KeyD)state.a+=2.7*dt;const boost=k.ShiftLeft||k.ShiftRight?1.8:1;state.vx+=Math.cos(state.a)*thrust*220*boost*dt;state.vy+=Math.sin(state.a)*thrust*220*boost*dt;const drag=Math.pow(.986,dt*60);state.vx*=drag;state.vy*=drag;const speed=Math.hypot(state.vx,state.vy),max=boost===1.8?480:270;if(speed>max){state.vx*=max/speed;state.vy*=max/speed}state.x+=state.vx*dt;state.y+=state.vy*dt;
 if(state.mouse.active){const sx=W/2,sy=H/2;state.a=Math.atan2(state.mouse.y-sy,state.mouse.x-sx)}if(k.Space||state.mouse.down||state.touchFire)shoot();
 if(performance.now()-state.lastDamage>2200&&state.shield<100){state.shield=Math.min(100,state.shield+9*dt);updateUI()}
 for(const r of state.rocks){r.x+=r.vx*dt;r.y+=r.vy*dt;r.a+=r.spin*dt;if(Math.hypot(r.x-state.x,r.y-state.y)>1700){const a=Math.random()*6.28;r.x=state.x+Math.cos(a)*rnd(1100,1450);r.y=state.y+Math.sin(a)*rnd(850,1150)}}
 for(const e of state.enemies){const dx=state.x-e.x,dy=state.y-e.y,d=Math.max(1,Math.hypot(dx,dy));e.a=Math.atan2(dy,dx);const target=d>320?1:d<200?-.6:.12;e.vx+=(dx/d)*target*90*dt+Math.cos(e.phase+state.frame*.0008)*28*dt;e.vy+=(dy/d)*target*90*dt+Math.sin(e.phase+state.frame*.0008)*28*dt;e.vx*=Math.pow(.985,dt*60);e.vy*=Math.pow(.985,dt*60);e.x+=e.vx*dt;e.y+=e.vy*dt;if(performance.now()>e.fireAt&&d<650){state.shots.push({x:e.x+Math.cos(e.a)*20,y:e.y+Math.sin(e.a)*20,vx:Math.cos(e.a)*250,vy:Math.sin(e.a)*250,life:2,player:false});e.fireAt=performance.now()+rnd(1600,2600)}}
 for(let i=state.shots.length-1;i>=0;i--){const s=state.shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.life<=0){state.shots.splice(i,1);continue}if(!s.player){if(Math.hypot(s.x-state.x,s.y-state.y)<19){state.shots.splice(i,1);damage(13)}continue}let hit=false;for(let j=state.rocks.length-1;j>=0;j--){const r=state.rocks[j];if(Math.hypot(s.x-r.x,s.y-r.y)<r.r){state.shots.splice(i,1);r.hp--;addParticle(s.x,s.y,'#ffd3a0',4,60);if(r.hp<=0)killRock(j);hit=true;break}}if(hit)continue;for(let j=state.enemies.length-1;j>=0;j--){const e=state.enemies[j];if(Math.hypot(s.x-e.x,s.y-e.y)<e.r){state.shots.splice(i,1);e.hp--;addParticle(s.x,s.y,'#ff9b88',5,80);if(e.hp<=0)killEnemy(j);break}}}
 for(let i=state.loot.length-1;i>=0;i--){const l=state.loot[i];if(state.magnet>0&&Math.hypot(l.x-state.x,l.y-state.y)<state.magnet){const d=Math.hypot(l.x-state.x,l.y-state.y)||1;l.x+=(state.x-l.x)/d*200*dt;l.y+=(state.y-l.y)/d*200*dt}if(Math.hypot(l.x-state.x,l.y-state.y)<35){state.loot.splice(i,1);if(l.type==='ore'){state.credits+=45;state.lootCollected++;toast('ORE CACHE RECOVERED // +₡45')}else{state.credits+=70;gainXP(28);toast('ENCRYPTED DATA // +₡70 // +28 XP')}updateUI();checkMission()}}
 for(let i=state.particles.length-1;i>=0;i--){const p=state.particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;p.life-=dt;if(p.life<=0)state.particles.splice(i,1)}
