function loop(now){const dt=Math.min(.04,(now-last)/1000);last=now;update(dt);render(dt);requestAnimationFrame(loop)}
const modalWrap=document.querySelector('#modalWrap'),modalTitle=document.querySelector('#modalTitle'),modalEyebrow=document.querySelector('#modalEyebrow'),modalBody=document.querySelector('#modalBody');
function openModal(title,eyebrow,html){modalTitle.textContent=title;modalEyebrow.textContent=eyebrow;modalBody.innerHTML=html;modalWrap.classList.add('open');state.paused=true;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyItem(b.dataset.buy))}
function closeModal(){modalWrap.classList.remove('open');state.paused=false;last=performance.now()}
function buyItem(id){const items={rapid:{price:380,name:'Overclocked Coil',desc:'Fire rate +35%',apply:()=>state.fireRate=Math.max(95,state.fireRate*.65)},plating:{price:300,name:'Reactive Plating',desc:'Hull capacity +35%',apply:()=>{state.hull=100}},shield:{price:260,name:'Shield Capacitor',desc:'Shield recharge +50%',apply:()=>state.shield=100},magnet:{price:220,name:'Salvage Magnet',desc:'Automatically pulls nearby loot',apply:()=>state.magnet=240},cannon:{price:520,name:'Heavy Pulse Cannon',desc:'Weapon damage +60%',apply:()=>state.damage=26}};const it=items[id];if(!it||state.credits<it.price){toast('INSUFFICIENT CREDITS');return}if(state.upgrades?.includes(id)){toast('UPGRADE ALREADY INSTALLED');return}state.credits-=it.price;state.upgrades??=[];state.upgrades.push(id);it.apply();updateUI();openTrade();toast(`${it.name.toUpperCase()} INSTALLED`)}
function openTrade(){openModal('Trade Exchange','KESTREL NETWORK // SHIP SERVICES',`<p class="intro">Salvage pays. Stay sharp out there, pilot. Your account: <b style="color:var(--amber)">₡ ${state.credits}</b></p><div class="item-row"><div class="item-icon">ϟ</div><div class="item-info"><strong>Overclocked Coil</strong><small>Fire rate +35% · installed: ${state.upgrades?.includes('rapid')?'YES':'NO'}</small></div><button class="buy" data-buy="rapid" ${state.upgrades?.includes('rapid')?'disabled':''}>₡ 380</button></div><div class="item-row"><div class="item-icon">⬡</div><div class="item-info"><strong>Reactive Plating</strong><small>Field repair + hull reinforcement · installed: ${state.upgrades?.includes('plating')?'YES':'NO'}</small></div><button class="buy" data-buy="plating" ${state.upgrades?.includes('plating')?'disabled':''}>₡ 300</button></div><div class="item-row"><div class="item-icon">◉</div><div class="item-info"><strong>Shield Capacitor</strong><small>Restore shields · recharge rate +50% · installed: ${state.upgrades?.includes('shield')?'YES':'NO'}</small></div><button class="buy" data-buy="shield" ${state.upgrades?.includes('shield')?'disabled':''}>₡ 260</button></div><div class="item-row"><div class="item-icon">⌖</div><div class="item-info"><strong>Salvage Magnet</strong><small>Automatically collect nearby loot · installed: ${state.upgrades?.includes('magnet')?'YES':'NO'}</small></div><button class="buy" data-buy="magnet" ${state.upgrades?.includes('magnet')?'disabled':''}>₡ 220</button></div><div class="item-row"><div class="item-icon">✳</div><div class="item-info"><strong>Heavy Pulse Cannon</strong><small>Weapon damage +60% · installed: ${state.upgrades?.includes('cannon')?'YES':'NO'}</small></div><button class="buy" data-buy="cannon" ${state.upgrades?.includes('cannon')?'disabled':''}>₡ 520</button></div><p class="notice">Destroy rocks for ore. Hunt raiders for bounties. Salvage everything.</p>`)}
function openComms(){openModal('Open Channel','INCOMING TRANSMISSION // MIRA VENN',`<div class="dialogue">“Wraith-7, you made it. Name’s Mira. I keep this station breathing while the syndicate picks the lanes clean. I can put a contract on your board—or point you toward work that pays better.”</div><button class="choice" data-choice="contract">“I’ll take the active contract.” <span style="float:right;color:var(--amber)">VIEW OBJECTIVE</span></button><button class="choice" data-choice="tip">“Any advice for a new pilot?” <span style="float:right;color:var(--amber)">FREE INTEL</span></button><button class="choice" data-choice="repair">“Can you patch me up?” <span style="float:right;color:var(--amber)">₡ 50</span></button><p class="notice">COMMS CHANNEL SECURE // PILOT ${String(state.level).padStart(2,'0')}</p>`);modalBody.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const c=b.dataset.choice;if(c==='contract'){closeModal();toast(`CONTRACT: ${missions[state.mission%missions.length].title.toUpperCase()}`)}else if(c==='tip'){openModal('Mira’s Advice','PILOT TO PILOT',`<div class="dialogue">“Wrecks leave ore and data. Pulse cannons do the job, but don’t sit still—scouts lead their shots. The trade board can turn a good run into a great ship. And if you see a station beacon, check in.”</div><button class="choice" id="tipDone">“Copy that. Thanks, Mira.”</button>`);document.querySelector('#tipDone').onclick=closeModal}else{if(state.credits<50)toast('NOT ENOUGH CREDITS');else{state.credits-=50;state.hull=100;state.shield=100;updateUI();toast('FIELD REPAIR COMPLETE // ₡50')}closeModal()}})}
function openHangar(){openModal('Ship Systems','WRAITH-7 // FLIGHT RECORD',`<div class="item-row"><div class="item-icon">⌁</div><div class="item-info"><strong>Pilot level ${state.level}</strong><small>${Math.floor(state.xp)} / ${state.level*100} XP to next rank · each rank: +₡75 & full repair</small></div></div><div class="item-row"><div class="item-icon">ϟ</div><div class="item-info"><strong>${state.weapon}</strong><small>${state.damage} damage per pulse · ${(1000/state.fireRate).toFixed(1)} shots/sec</small></div></div><div class="item-row"><div class="item-icon">⬡</div><div class="item-info"><strong>Installed upgrades</strong><small>${state.upgrades?.length?state.upgrades.map(x=>({rapid:'Overclocked Coil',plating:'Reactive Plating',shield:'Shield Capacitor',magnet:'Salvage Magnet',cannon:'Heavy Pulse Cannon'}[x])).join(' · '):'None — visit the trade exchange to upgrade'}</small></div></div><div class="item-row"><div class="item-icon">◎</div><div class="item-info"><strong>${state.visited.size} systems charted</strong><small>${[...state.visited].map(i=>systems[i].name).join(' · ')}</small></div></div><p class="notice">NAVIGATE WITH MOUSE AIM AND WASD THRUST. KEEP MOVING IN A FIGHT.</p>`)}
function openMap(){const nodes=systems.map((s,i)=>`<button class="map-node ${i===state.system?'current':''}" data-system="${i}"><span class="node-dot">${i===state.system?'●':state.visited.has(i)?'◉':'○'}</span><strong>${s.name}</strong><small>${s.desc}</small><small style="display:block;color:${s.color};margin-top:7px">${i===state.system?'CURRENT LOCATION':'JUMP // '+(i===0?'FREE':'₡ '+(i*35))}</small></button>`).join('');openModal('Sector Chart','FRONTIER NAVIGATION // 5 SYSTEMS',`<p class="intro">Select a charted beacon to make a short-range jump. Travel advances the frontier story and replenishes nearby hostiles.</p><div class="map-grid">${nodes}</div><p class="notice">NAV-COM FEE IS DEDUCTED ON ARRIVAL · CURRENT CONTRACT: ${missions[state.mission%missions.length].title.toUpperCase()}</p>`);modalBody.querySelectorAll('[data-system]').forEach(b=>b.onclick=()=>travel(Number(b.dataset.system)))}
function travel(i){if(i===state.system){toast('ALREADY IN THIS SYSTEM');return}const fee=i===0?0:35*i;if(state.credits<fee){toast('INSUFFICIENT CREDITS FOR NAV-COM');return}state.credits-=fee;state.system=i;state.x=systems[i].x+rnd(-70,70);state.y=systems[i].y+rnd(-70,70);state.vx=state.vy=0;state.visited.add(i);state.rocks=[];for(let n=0;n<18;n++){const a=Math.random()*6.28,d=rnd(260,1050);spawnRock(state.x+Math.cos(a)*d,state.y+Math.sin(a)*d,Math.random()<.25?3:2)}state.enemies=[];for(let n=0;n<3+(i>1?1:0);n++)spawnEnemy();ui.system.textContent=systems[i].name.toUpperCase();checkMission();updateUI();closeModal();toast(`JUMP COMPLETE // ${systems[i].name.toUpperCase()}`)}
function dock(){let best=-1,range=140;for(let i=0;i<systems.length;i++){const d=Math.hypot(systems[i].x-state.x,systems[i].y-state.y);if(d<range){range=d;best=i}}if(best<0){toast('NO BEACON IN RANGE // OPEN SECTOR MAP');return}state.system=best;state.visited.add(best);openModal(`${systems[best].name} Station`,'DOCKING CLAMPS ENGAGED',`<div class="dialogue">“Welcome in, pilot. ${best===0?'Mira’s got the trade exchange open. Take a look at the contract board before you head back out.':'Fresh stock, fresh fuel. Keep your transponder on and your cannons hot.'}”</div><button class="choice" id="dockTrade">⌘ &nbsp; Trade Exchange <span style="float:right;color:var(--amber)">SHIP UPGRADES</span></button><button class="choice" id="dockComms">◉ &nbsp; Speak with Mira <span style="float:right;color:var(--amber)">CONTRACTS & INTEL</span></button><button class="choice" id="dockLeave">↗ &nbsp; Undock and return to the frontier</button>`);document.querySelector('#dockTrade').onclick=openTrade;document.querySelector('#dockComms').onclick=openComms;document.querySelector('#dockLeave').onclick=closeModal;updateUI()}

