function openPause(){openModal('Flight Paused','WRAITH-7 // SYSTEM STANDBY',`<p class="intro">Your ship is holding position. Resume flight when you’re ready, pilot.</p><button class="choice" id="resume">▶ &nbsp; Resume flight</button><button class="choice" id="pauseMap">◎ &nbsp; Open sector chart</button><p class="notice">WASD THRUST · MOUSE AIM / FIRE · SHIFT BOOST · E DOCK</p>`);document.querySelector('#resume').onclick=closeModal;document.querySelector('#pauseMap').onclick=openMap}
function onKey(e,down){if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();state.keys[e.code]=down;if(down&&e.code==='KeyE')dock();if(down&&e.code==='KeyM')openMap();if(down&&e.code==='Escape'){if(modalWrap.classList.contains('open'))closeModal();else openPause()}}
