--function update(dt)
function update(dt){if(state.paused)return;state.frame+=dt*1000;const k=state.keys;let thrust=0;if(k.KeyW||k.ArrowUp)thrust=1;if(k.KeyS||k.ArrowDown)thrust=-.65;if(k.KeyA)state.a-=2.7*dt;if(k.KeyD)state.a+=2.7*dt;const boost=k.ShiftLeft||k.ShiftRight?1.8:1;state.vx+=Math.cos(state.a)*thrust*220*boost*dt;state.vy+=Math.sin(state.a)*thrust*220*boost*dt;const drag=Math.pow(.986,dt*60);state.vx*=drag;state.vy*=drag;const speed=Math.hypot(state.vx,state.vy),max=boost===1.8?480:270;if(speed>max){state.vx*=max/speed;state.vy*=max/speed}state.x+=state.vx*dt;state.y+=state.vy*dt;
 if(state.mouse.active){const sx=W/2,sy=H/2;state.a=Math.atan2(state.mouse.y-sy,state.mouse.x-sx)}if(k.Space||state.mouse.down||state.touchFire)shoot();
 if(performance.now()-state.lastDamage>2200&&state.shield<100){state.shield=Math.min(100,state.shield+9*dt);updateUI()}
 for(const r of state.rocks){r.x+=r.vx*dt;r.y+=r.

--function shoot()
function shoot(){const now=performance.now();if(now-state.lastShot<state.fireRate||state.paused)return;state.lastShot=now;const a=state.a;state.shots.push({x:state.x+Math.cos(a)*19,y:state.y+Math.sin(a)*19,vx:Math.cos(a)*state.shotSpeed+state.vx*.4,vy:Math.sin(a)*state.shotSpeed+state.vy*.4,life:1.45,player:true});addParticle(state.x+Math.cos(a)*19,state.y+Math.sin(a)*19,'#9bffff',3,55)}
function damage(amount){if(performance.now()-state.lastDamage<450)return;state.lastDamage=performance.now();const block=Math.min(state.shield,amount);state.shield-=block;state.hull=Math.max(0,state.hull-(amount-block));if(state.hull<=0){state.hull=68;state.shield=55;state.x=0;state.y=0;state.vx=state.vy=0;state.credits=Math.max(0,state.credits-65);state.shots=[];state.enemies=[];spawnEnemy();toast('EMERGENCY REBOOT // ₡65 RECOVERY FEE')}else toast('HULL IMPACT // SHIELDS RECHARGING');updateUI()}
